import{_ as a,o as t,c as o,ag as c}from"./chunks/framework.Pp2klvcf.js";const _=JSON.parse('{"title":"認證及 RBAC","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/server/api/auth-rbac.md","filePath":"zh-HK/server/api/auth-rbac.md","lastUpdated":1788681727000}'),r={name:"zh-HK/server/api/auth-rbac.md"};function d(s,e,n,i,h,u){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="認證及-rbac" tabindex="-1">認證及 RBAC <a class="header-anchor" href="#認證及-rbac" aria-label="Permalink to &quot;認證及 RBAC&quot;">​</a></h1><p><code>POST /auth/login</code> 發出 Access/Refresh Token；<code>/auth/refresh</code> 輪替 Token；<code>/auth/logout</code> 撤銷 Refresh Token；<code>GET /auth/me</code> 回傳目前用戶、角色及權限。</p><p>Access Token 以 <code>Authorization: Bearer &lt;token&gt;</code> 傳送。Refresh Token 不能當成 Access Token。Spring Security 依第一個 matcher 決定規則，因此公開白名單必須位於 <code>anyRequest().authenticated()</code> 之前。</p><p><code>analytics:view</code> 及 <code>data:view</code> 保護經營資料；<code>GET /menus</code> 只需登入以取得自己的選單，而管理端 <code>/menus/tree</code> 及 CRUD 使用 <code>menu:*</code> 權限。</p>',4)])])}const l=a(r,[["render",d]]);export{_ as __pageData,l as default};
